declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder\UserInvitationInvitedByAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationInvitedByAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationInvitedByAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getInvitedBy returns null on a freshly created holder.
     */
    public function testInvitedByNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationInvitedByAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isInvitedByAssigned());
        $this->assertNull($holder->getInvitedBy());
    }
}
class ImplWithUserInvitationInvitedByAttributeHolderUnitTest
{
    use UserInvitationInvitedByAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedInvitedByRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultInvitedBy();
    }
}
